mapper.select:
select t.heartbeat_time,t.heartbeat_time heartbeatTime,t.impl_bean,t.impl_bean
implBean,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code machineCode,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.machine_name,t.machine_name
machineName,t.machine_ip,t.machine_ip machineIp,t.direction,t.box_id,t.box_id boxId,pb.box_name
boxName,t.create_time createTime,hm.hm_name implBeanName,
hm.hm_id hmId
from barrier t
left join parking_box pb on t.box_id = pb.box_id and pb.status_cd = '0'
left join hardware_manufacturer hm on t.impl_bean = hm.hm_id and hm.status_cd = '0'
where 1 =1

    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.box_id= #{boxId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update barrier t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.heartbeat_time= #{heartbeatTime}


    , t.impl_bean= #{implBean}


    , t.machine_code= #{machineCode}


    , t.community_id= #{communityId}


    , t.machine_name= #{machineName}


    , t.machine_ip= #{machineIp}


    , t.direction= #{direction}


    , t.box_id= #{boxId}

where 1=1

    and t.machine_id= #{machineId}

mapper.select:
select count(1) count
from barrier t
where 1 =1

    and DATE_ADD(t.heartbeat_time, INTERVAL 2 MINUTE) < #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.box_id= #{boxId}

select t.heartbeat_time,t.heartbeat_time heartbeatTime,t.impl_bean,t.impl_bean
implBean,t.machine_id,t.machine_id machineId,t.machine_code,t.machine_code machineCode,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.machine_name,t.machine_name
machineName,t.machine_ip,t.machine_ip machineIp,t.direction,t.box_id,t.box_id boxId,pb.box_name
boxName,t.create_time createTime
from barrier t
left join parking_box pb on t.box_id = pb.box_id and pb.status_cd = '0'
left join parking_box_area pba on pb.box_id = pba.box_id and pba.status_cd = '0'
left join parking_area pa on pba.pa_id = pa.pa_id and pa.status_cd = '0'
where t.status_cd = '0'
and pa.pa_id = #{paId}

    and t.heartbeat_time= #{heartbeatTime}


    and t.impl_bean= #{implBean}


    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.machine_ip= #{machineIp}


    and t.direction= #{direction}


    and t.box_id= #{boxId}

order by t.create_time desc

    limit #{page}, #{row}
